const int gazeY[] = {0, 0, 0, -5, 5, 5, -3, -3, -3};
const int GAZE_COUNT = 9;

int targetGaze = 0;
uint32_t nextGazeAt = 0;

float eyeOffsetX = 0;
float eyeOffsetY = 0;

void updateGaze(uint32_t now) {
if (now >= nextGazeAt) {
