// -------------------- Blink --------------------

bool blinking = false;
bool secondBlinkPending = false;

uint32_t blinkStartedAt = 0;
uint32_t nextBlinkAt = 0;
uint32_t secondBlinkAt = 0;

int blinkDuration = 170;

void scheduleNextBlink(uint32_t now) {
nextBlinkAt = now + randomBetween(2200, 5200);
}

float getBlinkOpenness(uint32_t now) {
if (!blinking) return 1.0f;

uint32_t elapsed = now - blinkStartedAt;
int closeTime = 55;
int openTime = blinkDuration - closeTime - 22;

if (elapsed < (uint32_t)closeTime) {
return 1.0f - (float)elapsed / closeTime;
}

if (elapsed < (uint32_t)(closeTime + 22)) {
return 0.0f;
}

if (elapsed < (uint32_t)blinkDuration) {
return (float)(elapsed - closeTime - 22) / (float)openTime;
}

return 1.0f;
}

void updateBlink(uint32_t now) {
if (!blinking && now >= nextBlinkAt) {
blinking = true;
blinkStartedAt = now;
blinkDuration = randomBetween(150, 205);

secondBlinkPending = random(0, 4) == 0;

if (secondBlinkPending) {
secondBlinkAt = now + blinkDuration + randomBetween(100, 180);
}

scheduleNextBlink(now);

}

if (blinking && now - blinkStartedAt >= (uint32_t)blinkDuration) {
blinking = false;
}

if (!blinking && secondBlinkPending && now >= secondBlinkAt) {
blinking = true;
blinkStartedAt = now;
blinkDuration = randomBetween(145, 190);
secondBlinkPending = false;
}
}

// -------------------- Mood --------------------

void setMood(FaceMood newMood, uint32_t now) {
faceMood = newMood;

switch (newMood) {
case MOOD_NORMAL:
moodEndsAt = 0;
break;
case MOOD_HAPPY:
moodEndsAt = now + randomBetween(2500, 4000);
break;
case MOOD_SURPRISED:
moodEndsAt = now + randomBetween(1800, 2800);
break;
case MOOD_SLEEPY:
moodEndsAt = now + randomBetween(3000, 4500);
break;
case MOOD_ANGRY:
case MOOD_CRYING:
moodEndsAt = now + randomBetween(2500, 4000);
break;
case MOOD_UPSET:
moodEndsAt = now + randomBetween(2500, 4000);
break;
}
}

void updateMood(uint32_t now) {
if (faceMood != MOOD_NORMAL && moodEndsAt != 0 && now >= moodEndsAt) {
setMood(MOOD_NORMAL, now);
nextMoodAt = now + randomBetween(10000, 15000);
}

if (faceMood == MOOD_NORMAL && now >= nextMoodAt) {
int choice = random(0, 4);

switch (choice) {
case 0: setMood(MOOD_HAPPY, now); break;
case 1: setMood(MOOD_SURPRISED, now); break;
case 2: setMood(MOOD_SLEEPY, now); break;
default: setMood(MOOD_UPSET, now); break;
}

nextMoodAt = now + randomBetween(10000, 15000);

}
}

// -------------------- Serial control --------------------

void readSerialCommand(uint32_t now) {
while (Serial.available() > 0) {
char command = Serial.read();

switch (command) {
case 'n':
case 'N': setMood(MOOD_NORMAL, now); break;
case 'h':
case 'H': setMood(MOOD_HAPPY, now); break;
case 's':
case 'S': setMood(MOOD_SURPRISED, now); break;
case 'z':
case 'Z': setMood(MOOD_SLEEPY, now); break;
case 'a':
case 'A': setMood(MOOD_ANGRY, now); break;
case 'u':
case 'U': setMood(MOOD_UPSET, now); break;
case 'c':
case 'C': setMood(MOOD_CRYING, now); break;
}

}
